459	    /// Collect the `type` of every frame produced for a sequence of events.
460	    fn types(events: &[AgentEvent]) -> Vec<String> {
461	        let mut m = mapper();
462	        let mut out = Vec::new();
463	        for e in events {
464	            for f in m.push(e) {
465	                out.push(f["type"].as_str().unwrap().to_owned());
466	            }
467	        }
468	        for f in m.finish() {
469	            out.push(f["type"].as_str().unwrap().to_owned());
470	        }
471	        out
472	    }
