510	    /// open at a time, every `TOOL_CALL_ARGS` carried by the call that is open (so
511	    /// no id's args can leak outside its own span), every `END` matching whichever
512	    /// call is open, and nothing left open by the end of the sequence.
513	    ///
514	    /// Nesting only — [`assert_tool_calls_well_formed`] is the full invariant and is
515	    /// what tests should normally use. This weaker form exists for the one ordering
516	    /// that cannot satisfy the stronger one: a delta revisiting an id whose span a
517	    /// foreign event already closed can only be rendered as a *second* span for that
518	    /// id (see `a_delta_revisiting_a_closed_id_keeps_its_args_and_its_name`).
519	    /// Regression (CodeRabbit, PR #186): a `MessageOutput` synthesizing its own text
520	    /// triple must not nest that triple inside a still-open tool call. Reachable today
521	    /// with a `ToolCallDelta` followed by a `MessageOutput` that streamed no deltas.
522	    #[test]
523	    fn a_synthesized_message_does_not_nest_inside_an_open_tool_call() {
524	        let mut m = EventMapper::new("t".to_owned(), "r".to_owned());
525	        let mut frames = Vec::new();
526	        frames.extend(m.push(&AgentEvent::ToolCallDelta {
527	            call_id: "tc1".to_owned(),
528	            name: Some("search".to_owned()),
529	            args_delta: "{}".to_owned(),
530	        }));
531	        frames.extend(m.push(&AgentEvent::MessageOutput {
532	            item: Item::AssistantMessage {
533	                content: vec![ContentPart::Text {
534	                    text: "done".to_owned(),
535	                }],
536	                agent: None,
537	            },
538	        }));
539	        frames.extend(m.finish());
540	        assert_tool_call_nesting(&frames);
541	    }
542	
543	    /// Regression (CodeRabbit, PR #186): a tool-call span must not cross a
544	    /// `STEP_FINISHED`/`STEP_STARTED` boundary.
545	    #[test]
546	    fn a_tool_call_span_does_not_cross_a_turn_boundary() {
547	        let mut m = EventMapper::new("t".to_owned(), "r".to_owned());
548	        let mut frames = Vec::new();
549	        frames.extend(m.push(&AgentEvent::TurnStarted { turn: 1 }));
550	        frames.extend(m.push(&AgentEvent::ToolCallDelta {
551	            call_id: "tc1".to_owned(),
552	            name: Some("search".to_owned()),
553	            args_delta: "{}".to_owned(),
554	        }));
555	        frames.extend(m.push(&AgentEvent::TurnStarted { turn: 2 }));
556	        frames.extend(m.finish());
557	        assert_tool_call_nesting(&frames);
558	    }
559	
560	    fn assert_tool_call_nesting(frames: &[Value]) {
561	        let mut open: Option<&str> = None;
562	        for f in frames {
563	            match f["type"].as_str().unwrap() {
564	                "TOOL_CALL_START" => {
565	                    let id = f["toolCallId"].as_str().unwrap();
566	                    assert!(
567	                        open.is_none(),
568	                        "TOOL_CALL_START for {id:?} while {open:?} is still open: {frames:?}"
569	                    );
570	                    open = Some(id);
571	                }
572	                "TOOL_CALL_ARGS" => {
573	                    let id = f["toolCallId"].as_str().unwrap();
574	                    assert_eq!(
575	                        open,
576	                        Some(id),
577	                        "TOOL_CALL_ARGS for {id:?} outside that call's own span \
578	                         (open: {open:?}): {frames:?}"
579	                    );
580	                }
581	                "TOOL_CALL_END" => {
582	                    let id = f["toolCallId"].as_str().unwrap();
583	                    assert_eq!(
584	                        open,
585	                        Some(id),
586	                        "TOOL_CALL_END for {id:?} does not match the open call {open:?}: {frames:?}"
587	                    );
588	                    open = None;
589	                }
590	                // Nothing else may appear inside a call's span. Checking only the
591	                // `TOOL_CALL_*` frames would let a text triple or a step boundary nest
592	                // inside an open call and still pass — which is exactly how two
593	                // missing `close_call`s once went unnoticed here.
594	                other => {
595	                    assert!(
596	                        open.is_none(),
597	                        "{other} emitted while tool call {open:?} is still open: {frames:?}"
598	                    );
599	                }
600	            }
601	        }
602	        assert!(open.is_none(), "a tool call was left open: {frames:?}");
603	    }
604	
605	    /// Assert every tool-call invariant the mapper owes an AG-UI client, for the
606	    /// `frames` produced by `events`:
607	    ///
608	    /// 1. spans nest and never overlap ([`assert_tool_call_nesting`]);
609	    /// 2. each call id opens **at most once** across the whole sequence — a nesting
610	    ///    check cannot see a duplicate `START`, yet one call split across two spans
611	    ///    is exactly what breaks a client that keys state on `toolCallId`;
612	    /// 3. each id's args are emitted **in receipt order and in full** — concatenating
613	    ///    the `TOOL_CALL_ARGS` deltas the mapper emitted for an id must reproduce the
614	    ///    concatenation of that id's `ToolCallDelta` chunks in the order they arrived.
615	    ///    Reordering or dropping a chunk yields malformed JSON on the client, and (1)
616	    ///    and (2) are both blind to it.
617	    ///
618	    /// Ids with no `ToolCallDelta` at all (a non-streaming provider's `ToolCallItem`)
619	    /// carry no receipt order to check, so (3) skips them.
620	    fn assert_tool_calls_well_formed(events: &[AgentEvent], frames: &[Value]) {
621	        assert_tool_call_nesting(frames);
622	
623	        let mut started: Vec<&str> = Vec::new();
624	        for f in frames.iter().filter(|f| f["type"] == "TOOL_CALL_START") {
625	            let id = f["toolCallId"].as_str().unwrap();
626	            assert!(
627	                !started.contains(&id),
628	                "TOOL_CALL_START for {id:?} emitted twice — one call must map to \
629	                 exactly one span: {frames:?}"

